 "content": "def transform(grid):
    """Shear every colored cell left by its distance above the object's bottom row."""
    out = [[0 for _ in row] for row in grid]
    colored_rows = [r for r, row in enumerate(grid) if any(row)]
    if not colored_rows:
        return out
    bottom = max(colored_rows)
    width = len(grid[0]) if grid else 0
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, value in enumerate(row):
            if value:
                nc = c + shift
                if 0 <= nc < width:
                    out[r][nc] = value
    return out
